// Diagrams for the Night Rite pattern guides. Plain SVG markup, so the web
// renders the same drawing the iPhone app bundles (as PDF assets generated by
// scripts/generate-rite-diagrams.py). Static, trusted content only.

export type RiteDiagram =
  | 'escape-goal'
  | 'escape-turns'
  | 'lab-pour'
  | 'lab-turns'
  | 'riddle-map'
  | 'riddle-cards'
  | 'riddle-terms'
  | 'ritual-roles'
  | 'ritual-book';

// Text alternative for each drawing.
export const DIAGRAM_ALT: Record<RiteDiagram, string> = {
  'escape-goal':
    'A six by six board. The red carriage sits in the third row and must slide right through the gap in the fence. Arrows show pieces sliding only along their length.',
  'escape-turns':
    'Four players in a ring take turns in a random order, each with a five-second timer for one slide.',
  'lab-pour':
    'Two red layers on top of one vial pour onto a vial topped with red that has room for two.',
  'lab-turns':
    'Four players in a ring take turns in a random order, each with an eight-second timer for one pour.',
  'riddle-map':
    'Five places along one street from west to east: Library, Garden, House, Market, Graveyard. Each has a spot for a person and an activity.',
  'riddle-cards':
    'Four clue cards: two open on the Rite’s first night, one on the second and one on the third.',
  'riddle-terms':
    'Examples on the street: next door means neighbouring places; two doors west means one place between them; one end of the street means the first or last place.',
  'ritual-roles':
    'The omens holder reads symbols aloud, the grimoire keeper turns them into a setting, and the performer sets the altar.',
  'ritual-book':
    'A grimoire entry turns a set of three symbols into one altar setting. Look-alike symbols such as a skull and a skull and crossbones never appear in the same set.',
};

const FONT = `font-family="Georgia, 'DejaVu Serif', serif"`;
const GOLD = '#d4ae4f',
  CREAM = '#efe1b4',
  DIM = '#a99a73';
function frame(id: string, body: string) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 160" width="320" height="160" ${FONT}><defs><linearGradient id="${id}-bg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1f1d1b"/><stop offset="1" stop-color="#34261c"/></linearGradient><marker id="${id}-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="${GOLD}"/></marker></defs><rect width="320" height="160" rx="10" fill="url(#${id}-bg)"/>${body}</svg>`;
}
const text = (
  x: number,
  y: number,
  s: string,
  size = 11,
  fill = CREAM,
  anchor = 'start',
  weight = 'normal',
) =>
  `<text x="${x}" y="${y}" font-size="${size}" fill="${fill}" text-anchor="${anchor}" font-weight="${weight}">${s}</text>`;
const arrow = (id: string, d: string, dash = false) =>
  `<path d="${d}" fill="none" stroke="${GOLD}" stroke-width="2"${dash ? ' stroke-dasharray="4 3"' : ''} marker-end="url(#${id}-arrow)"/>`;

// --- Escape Fearville -------------------------------------------------------
function escapeGoal() {
  const id = 'dg-escape-goal',
    c = 19,
    ox = 18,
    oy = 22;
  const cell = (x: number, y: number) => [ox + x * c, oy + y * c];
  const piece = (
    x: number,
    y: number,
    w: number,
    h: number,
    fill: string,
    stroke = '#2a1d12',
  ) => {
    const [px, py] = cell(x, y);
    return `<rect x="${px + 1.5}" y="${py + 1.5}" width="${w * c - 3}" height="${h * c - 3}" rx="4" fill="${fill}" stroke="${stroke}" stroke-width="1.5"/>`;
  };
  let grid = '';
  for (let i = 0; i <= 6; i++)
    grid += `<path d="M${ox + i * c} ${oy}V${oy + 6 * c}M${ox} ${oy + i * c}H${ox + 6 * c}" stroke="#ffffff" stroke-opacity=".08"/>`;
  const [gx, gy] = cell(6, 2);
  const fence = `<path d="M${ox + 6 * c + 3} ${gy}V${oy - 3}H${ox - 3}V${oy + 6 * c + 3}H${ox + 6 * c + 3}V${gy + c}" fill="none" stroke="${DIM}" stroke-width="3" stroke-linejoin="round"/>`;
  return frame(
    id,
    `<rect x="${ox}" y="${oy}" width="${6 * c}" height="${6 * c}" fill="#2d3a2a"/>${grid}${fence}` +
      piece(0, 2, 2, 1, '#c8423b', '#f3d0a6') +
      piece(3, 1, 1, 3, '#8a5a2b') +
      piece(4, 0, 2, 1, '#6f7a85') +
      piece(5, 3, 1, 2, '#a2703c') +
      piece(1, 4, 3, 1, '#5d7a3a') +
      piece(0, 0, 1, 2, '#8a5a2b') +
      arrow(id, `M${ox + 2 * c + 4} ${gy + c / 2}H${gx + 24}`, true) +
      // Track arrows: up-down on the upright log, left-right on the felled tree.
      `<path d="M${ox + 3.5 * c} ${oy + 1 * c + 5}v${3 * c - 10}" stroke="${CREAM}" stroke-width="1.5" marker-start="url(#${id}-arrow)" marker-end="url(#${id}-arrow)"/>` +
      `<path d="M${ox + 1 * c + 6} ${oy + 4.5 * c}h${3 * c - 12}" stroke="${CREAM}" stroke-width="1.5" marker-start="url(#${id}-arrow)" marker-end="url(#${id}-arrow)"/>` +
      text(gx + 16, gy - 4, 'EXIT', 9, GOLD, 'middle', 'bold') +
      text(178, 42, 'Slide the red carriage', 12, CREAM) +
      text(178, 57, 'out through the gap.', 12, CREAM) +
      `<rect x="178" y="76" width="30" height="13" rx="3" fill="#c8423b"/>` +
      text(214, 87, 'your carriage', 10, DIM) +
      text(178, 112, 'Pieces slide only', 12, CREAM) +
      text(178, 127, 'along their length.', 12, CREAM),
  );
}
function turns(kind: 'escape' | 'lab') {
  const id = `dg-${kind}-turns`,
    cx = 82,
    cy = 82,
    r = 48;
  const spots = [0, 1, 2, 3].map((i) => {
    const a = -Math.PI / 2 + (i * Math.PI) / 2;
    return [cx + r * Math.cos(a), cy + r * Math.sin(a)];
  });
  let body = `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${GOLD}" stroke-width="1.5" stroke-dasharray="3 5"/>`;
  for (let i = 0; i < 4; i++) {
    const a1 = -Math.PI / 2 + (i * Math.PI) / 2 + 0.38,
      a2 = a1 + Math.PI / 2 - 0.76;
    body += arrow(
      id,
      `M${cx + r * Math.cos(a1)} ${cy + r * Math.sin(a1)}A${r} ${r} 0 0 1 ${cx + r * Math.cos(a2)} ${cy + r * Math.sin(a2)}`,
    );
  }
  spots.forEach(([x, y], i) => {
    body += `<circle cx="${x}" cy="${y}" r="14" fill="${i === 0 ? GOLD : '#3b3226'}" stroke="${GOLD}" stroke-width="2"/>`;
    body += text(
      x,
      y + 4,
      i === 0 ? 'You' : String(i + 1),
      i === 0 ? 9 : 11,
      i === 0 ? '#2a1d12' : CREAM,
      'middle',
      'bold',
    );
  });
  const secs = kind === 'escape' ? '5' : '8';
  body += `<circle cx="${cx}" cy="${cy}" r="19" fill="#2a2119" stroke="#c8423b" stroke-width="2.5"/>`;
  body += text(cx, cy + 5, `${secs}s`, 14, CREAM, 'middle', 'bold');
  body +=
    text(160, 40, 'Turn order is random', 12, CREAM) +
    text(160, 55, 'each night.', 12, CREAM) +
    text(
      160,
      84,
      `One ${kind === 'escape' ? 'slide' : 'pour'} per turn,`,
      12,
      CREAM,
    ) +
    text(160, 99, `${secs} seconds to make it.`, 12, CREAM) +
    text(160, 128, 'Done early? The turn', 11, DIM) +
    text(160, 142, 'passes at once.', 11, DIM);
  return frame(id, body);
}

// --- Alchemist's Laboratory -----------------------------------------------
const LIQ = ['#50bf43', '#d73142', '#3164d8', '#9250c5'];
function vial(x: number, layers: number[], label: string, faded = false) {
  const w = 30,
    h = 84,
    y = 30,
    u = 19;
  let s = `<g opacity="${faded ? 0.55 : 1}">`;
  layers.forEach((c, i) => {
    s += `<rect x="${x + 3}" y="${y + h - 4 - (i + 1) * u}" width="${w - 6}" height="${u}" fill="${LIQ[c]}"/>`;
  });
  s += `<path d="M${x} ${y}V${y + h - 6}Q${x} ${y + h} ${x + 6} ${y + h}H${x + w - 6}Q${x + w} ${y + h} ${x + w} ${y + h - 6}V${y}" fill="none" stroke="#bdd5dc" stroke-width="2"/>`;
  s += `<path d="M${x - 3} ${y}H${x + w + 3}" stroke="#c5dce1" stroke-width="2"/></g>`;
  return s + text(x + w / 2, 132, label, 10, DIM, 'middle');
}
function labPour() {
  const id = 'dg-lab-pour';
  return frame(
    id,
    vial(14, [2, 1, 1], 'from') +
      vial(60, [3, 1], 'to') +
      arrow(id, 'M40 42Q60 12 74 34') +
      text(57, 20, 'pour', 10, GOLD, 'middle') +
      `<path d="M98 74H112" stroke="${GOLD}" stroke-width="2" marker-end="url(#${id}-arrow)"/>` +
      vial(120, [2], '') +
      vial(156, [3, 1, 1, 1], '') +
      text(153, 132, 'after', 10, DIM, 'middle') +
      text(194, 40, 'The top run pours', 10.5, CREAM) +
      text(194, 54, 'onto the same liquid', 10.5, CREAM) +
      text(194, 68, 'or into an empty vial.', 10.5, CREAM) +
      text(194, 82, 'Each vial holds four.', 10.5, CREAM) +
      text(194, 112, 'Win: one liquid', 10.5, GOLD) +
      text(194, 126, 'in every vial.', 10.5, GOLD),
  );
}

// --- The Sphinx's Riddles --------------------------------------------------
const PLACES = ['Library', 'Garden', 'House', 'Market', 'Graveyard'];
function street(id: string, y: number, highlight: number[] = []) {
  let s = `<rect x="14" y="${y + 30}" width="292" height="14" rx="7" fill="#3a3326"/><path d="M22 ${y + 37}H298" stroke="${GOLD}" stroke-opacity=".45" stroke-dasharray="8 6"/>`;
  PLACES.forEach((p, i) => {
    const x = 42 + i * 59;
    const on = highlight.includes(i);
    s += `<path d="M${x - 16} ${y + 26}V${y + 10}L${x} ${y}L${x + 16} ${y + 10}V${y + 26}Z" fill="${on ? GOLD : '#5a4b35'}" stroke="${on ? CREAM : '#2a1d12'}" stroke-width="1.5"/>`;
    s += `<rect x="${x - 4}" y="${y + 16}" width="8" height="10" fill="#2a1d12"/>`;
    s += text(x, y + 58, p, 9.5, CREAM, 'middle');
  });
  return s + `<g id="${id}-street"/>`;
}
function riddleMap() {
  const id = 'dg-riddle-map';
  let s = street(id, 30);
  [0, 1, 2, 3, 4].forEach((i) => {
    const x = 42 + i * 59;
    s += `<circle cx="${x - 6}" cy="${118}" r="10" fill="none" stroke="${GOLD}" stroke-dasharray="3 2"/><circle cx="${x + 8}" cy="${124}" r="6.5" fill="none" stroke="${DIM}" stroke-dasharray="2 2"/>`;
  });
  s +=
    `<path d="M58 17H262" stroke="${GOLD}" stroke-width="2" marker-start="url(#${id}-arrow)" marker-end="url(#${id}-arrow)"/>` +
    text(14, 21, 'WEST', 10, GOLD, 'start', 'bold') +
    text(306, 21, 'EAST', 10, GOLD, 'end', 'bold') +
    text(160, 150, 'Each place: one person, one activity', 10, DIM, 'middle');
  return frame(id, s);
}
function riddleCards() {
  const id = 'dg-riddle-cards';
  const labels = [
    ['1st Rite', 'night'],
    ['1st Rite', 'night'],
    ['2nd Rite', 'night'],
    ['3rd Rite', 'night'],
  ];
  let s = '';
  labels.forEach(([a, b], i) => {
    const x = 20 + i * 74,
      y = 22 + (i % 2) * 4;
    const open = i < 2;
    s += `<g transform="rotate(${(i - 1.5) * 3} ${x + 30} ${y + 50})"><rect x="${x}" y="${y}" width="60" height="84" rx="6" fill="${open ? '#efe1b4' : '#3b3226'}" stroke="${GOLD}" stroke-width="2"/>`;
    s += open
      ? `<path d="M${x + 10} ${y + 22}H${x + 50}M${x + 10} ${y + 32}H${x + 46}M${x + 10} ${y + 42}H${x + 50}M${x + 10} ${y + 52}H${x + 38}" stroke="#7a6a48" stroke-width="2"/>`
      : `<rect x="${x + 22}" y="${y + 36}" width="16" height="13" rx="2" fill="${GOLD}"/><path d="M${x + 25} ${y + 36}V${y + 31}a5 5 0 0 1 10 0V${y + 36}" fill="none" stroke="${GOLD}" stroke-width="2"/>`;
    s += `</g>`;
    s +=
      text(x + 30, 126, a, 9.5, CREAM, 'middle') +
      text(x + 30, 138, b, 9.5, CREAM, 'middle');
  });
  return frame(
    id,
    s + text(160, 154, 'Read yours aloud by day', 10, GOLD, 'middle'),
  );
}
function riddleTerms() {
  const id = 'dg-riddle-terms';
  const row = (
    y: number,
    label: string,
    marks: Record<number, string>,
    extra = '',
  ) => {
    let s = text(12, y + 4, label, 10.5, CREAM);
    for (let i = 0; i < 5; i++) {
      const x = 166 + i * 32;
      const m = marks[i];
      s += `<circle cx="${x}" cy="${y}" r="9" fill="${m ? (m === '•' ? GOLD : '#c8423b') : '#3b3226'}" stroke="${GOLD}" stroke-width="1.2"/>`;
      if (m && m !== '•') s += text(x, y + 4, m, 10, CREAM, 'middle', 'bold');
    }
    return s + extra;
  };
  return frame(
    id,
    text(166, 18, 'W', 9, DIM, 'middle') +
      text(294, 18, 'E', 9, DIM, 'middle') +
      row(40, 'A is next door to B', { 1: 'A', 2: 'B' }) +
      row(
        72,
        'A is two doors west of B',
        { 1: 'A', 3: 'B' },
        `<path d="M207 58H253" stroke="${GOLD}" stroke-width="1.5" marker-end="url(#${id}-arrow)"/>`,
      ) +
      row(104, 'A is somewhere west of B', { 0: 'A', 3: 'B' }) +
      row(136, 'At one end of the street', { 0: '•', 4: '•' }),
  );
}

// --- Ritual of Divination --------------------------------------------------
function skull(x: number, y: number, s = 1) {
  return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M-7 0a7 7 0 1 1 14 0v4h-3v3h-8v-3h-3z" fill="${CREAM}"/><circle cx="-3" cy="0" r="2" fill="#2a1d12"/><circle cx="3" cy="0" r="2" fill="#2a1d12"/></g>`;
}
function crossbones(x: number, y: number) {
  return `<path d="M${x - 9} ${y - 6}L${x + 9} ${y + 10}M${x + 9} ${y - 6}L${x - 9} ${y + 10}" stroke="${CREAM}" stroke-width="2.5" stroke-linecap="round"/>${skull(x, y - 2, 0.85)}`;
}
function moon(x: number, y: number, flip = false) {
  return `<path transform="translate(${x} ${y}) scale(${flip ? -1 : 1} 1)" d="M3 -7.4A8 8 0 1 0 3 7.4A8.5 8.5 0 0 1 3 -7.4Z" fill="${CREAM}"/>`;
}
function glass(x: number, y: number) {
  return `<path d="M${x - 6} ${y - 8}H${x + 6}L${x - 6} ${y + 8}H${x + 6}Z" fill="none" stroke="${CREAM}" stroke-width="2" stroke-linejoin="round"/>`;
}
function crow(x: number, y: number) {
  return `<path d="M${x - 9} ${y}Q${x - 4} ${y - 7} ${x} ${y - 1}Q${x + 4} ${y - 7} ${x + 9} ${y}" fill="none" stroke="${CREAM}" stroke-width="2.5" stroke-linecap="round"/>`;
}
function ritualRoles() {
  const id = 'dg-ritual-roles';
  const node = (x: number, y: number, title: string, icon: string) =>
    `<circle cx="${x}" cy="${y}" r="24" fill="#3b3226" stroke="${GOLD}" stroke-width="2"/>${icon}${text(x, y + 40, title, 10.5, CREAM, 'middle', 'bold')}`;
  const book = `<path d="M150 46l10 4l10-4v20l-10 4l-10-4z" fill="${CREAM}"/><path d="M160 50v20" stroke="#3b3226" stroke-width="1.5"/>`;
  const candles = `<rect x="261" y="52" width="5" height="14" fill="${CREAM}"/><rect x="269" y="48" width="5" height="18" fill="${CREAM}"/><rect x="277" y="54" width="5" height="12" fill="${CREAM}"/><path d="M263.5 49q2-3 0-5q-2 2 0 5M271.5 45q2-3 0-5q-2 2 0 5M279.5 51q2-3 0-5q-2 2 0 5" fill="#f6a265"/>`;
  return frame(
    id,
    node(50, 58, 'Omens holder', skull(43, 56, 0.75) + moon(56, 58)) +
      node(160, 58, 'Grimoire keeper', book) +
      node(270, 58, 'Performer', candles) +
      arrow(id, 'M78 50H130') +
      arrow(id, 'M188 50H240') +
      text(104, 40, 'reads aloud', 9.5, GOLD, 'middle') +
      text(214, 40, 'says the setting', 9.5, GOLD, 'middle') +
      text(
        160,
        128,
        'Each of you plays all three parts,',
        11,
        CREAM,
        'middle',
      ) +
      text(160, 143, 'for three different rituals.', 11, CREAM, 'middle'),
  );
}
function ritualBook() {
  const id = 'dg-ritual-book';
  return frame(
    id,
    `<rect x="14" y="16" width="292" height="62" rx="6" fill="${CREAM}" fill-opacity=".06" stroke="${GOLD}" stroke-opacity=".6"/>` +
      skull(46, 47) +
      moon(76, 47) +
      glass(104, 47) +
      arrow(id, 'M124 47H150') +
      `<rect x="160" y="34" width="9" height="20" fill="#d73142"/><rect x="173" y="34" width="9" height="20" fill="#efe1b4" opacity=".35"/><rect x="186" y="34" width="9" height="20" fill="#9250c5"/>` +
      text(204, 43, 'Candles:', 10.5, GOLD) +
      text(204, 57, 'red, purple lit', 10.5, CREAM) +
      text(160, 98, 'Never in the same set:', 10.5, CREAM, 'middle') +
      skull(36, 126) +
      crossbones(62, 126) +
      moon(110, 126) +
      moon(134, 126, true) +
      crow(184, 126) +
      `<path d="M206 130q4-9 9-4q5-5 9 4" fill="none" stroke="${CREAM}" stroke-width="2.5"/><path d="M213 132v5" stroke="${CREAM}" stroke-width="2"/>` +
      glass(258, 126) +
      `<path d="M276 118q6 4 0 8q-6 4 0 8M288 118q-6 4 0 8q6 4 0 8" fill="none" stroke="${CREAM}" stroke-width="2"/><path d="M276 118h12M276 134h12" stroke="${CREAM}" stroke-width="2"/>` +
      [49, 122, 197, 268]
        .map(
          (x) =>
            `<path d="M${x - 26} 108H${x + 26}" stroke="${GOLD}" stroke-opacity=".5"/>`,
        )
        .join(''),
  );
}

export const RITE_DIAGRAMS: Record<RiteDiagram, string> = {
  'escape-goal': escapeGoal(),
  'escape-turns': turns('escape'),
  'lab-pour': labPour(),
  'lab-turns': turns('lab'),
  'riddle-map': riddleMap(),
  'riddle-cards': riddleCards(),
  'riddle-terms': riddleTerms(),
  'ritual-roles': ritualRoles(),
  'ritual-book': ritualBook(),
};
// iPhone asset catalog name for each diagram.
export const iosDiagramAsset = (d: RiteDiagram) => `RiteDiagram-${d}`;
